export default function build({ THREE, traits, ui, isGrabbed, assets }) {
  const root = new THREE.Group();

  const scope = assets.get('microscope-objaverse');
  root.add(scope.object3D);
  scope.object3D.scale.setScalar(1.1);

  const steps = [
    { id: 'eyepiece', title: 'Eyepiece (ocular lens)',
      text: 'You look through it. It magnifies the image a second time, usually 10x.' },
    { id: 'body_tube', title: 'Body tube',
      text: 'Holds the eyepiece and the objective lenses at the right distance and carries the light path between them.' },
    { id: 'objective_lenses', title: 'Objective lenses',
      text: 'Several lenses on a revolving nosepiece, often 4x, 10x, 40x and 100x. Total magnification = eyepiece x objective, so 10x with 40x gives 400x.' },
    { id: 'stage', title: 'Stage',
      text: 'The flat platform that holds the slide. Clips keep it still, and a hole in the middle lets light pass up through the specimen.' },
    { id: 'focus_knob', title: 'Focus knob',
      text: 'Moves the stage or tube up and down to make the image sharp. Use the large coarse knob first, then the small fine knob.' },
    { id: 'base', title: 'Base',
      text: 'The heavy foot that keeps the microscope steady. It usually holds the light source that shines up through the slide.' },
  ];

  const labelTexts = {
    eyepiece: 'Eyepiece', body_tube: 'Body tube', objective_lenses: 'Objective lenses',
    stage: 'Stage', focus_knob: 'Focus knob', base: 'Base',
  };
  const labels = {};
  steps.forEach((s) => {
    labels[s.id] = scope.label(s.id, labelTexts[s.id]);
    labels[s.id].setVisible(false);
  });

  const panel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .step { color: #8fb4ff; font-size: 20px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
              border-radius: 12px; background-color: #3a4049; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
      .credit { color: #9aa1ab; font-size: 18px; }
    </style>
    <div class="card">
      <span class="step" id="step">Part 1 of 6</span>
      <span class="title" id="title">Eyepiece</span>
      <span class="body" id="body">Pinch or poke a part, or use Next.</span>
      <div class="row">
        <button class="btn" id="prev"><span class="bt">Back</span></button>
        <button class="btn" id="next"><span class="bt">Next</span></button>
        <button class="btn2" id="all"><span class="bt">All labels</span></button>
      </div>
      <div class="row">
        <button class="btn2" id="explode"><span class="bt" id="explodeT">Explode</span></button>
        <button class="btn2" id="xray"><span class="bt" id="xrayT">X-ray</span></button>
        <button class="btn2" id="reset"><span class="bt">Reset</span></button>
      </div>
      <span class="credit">${scope.credit}</span>
    </div>`, { width: 0.36, position: [0, 0.5, 0] });
  root.add(panel.object3D);

  let current = 0;
  let showAll = false;
  let explodeTarget = 0;
  let explodeNow = 0;
  let xray = false;

  function refresh() {
    const s = steps[current];
    panel.set('step', { text: 'Part ' + (current + 1) + ' of ' + steps.length });
    panel.set('title', { text: s.title });
    panel.set('body', { text: s.text });
    steps.forEach((st, i) => labels[st.id].setVisible(showAll || i === current));
    scope.highlight(s.id);
  }

  function select(i) {
    current = (i + steps.length) % steps.length;
    showAll = false;
    refresh();
  }

  panel.on('next', 'click', () => select(current + 1));
  panel.on('prev', 'click', () => select(current - 1));
  panel.on('all', 'click', () => {
    showAll = !showAll;
    refresh();
  });
  panel.on('explode', 'click', () => {
    explodeTarget = explodeTarget > 0 ? 0 : 0.6;
    panel.set('explodeT', { text: explodeTarget > 0 ? 'Assemble' : 'Explode' });
  });
  panel.on('xray', 'click', () => {
    xray = !xray;
    scope.xray(xray, [steps[current].id]);
    panel.set('xrayT', { text: xray ? 'Solid' : 'X-ray' });
  });
  panel.on('reset', 'click', () => {
    explodeTarget = 0;
    explodeNow = 0;
    xray = false;
    showAll = false;
    current = 0;
    scope.reset();
    panel.set('explodeT', { text: 'Explode' });
    panel.set('xrayT', { text: 'X-ray' });
    refresh();
  });

  steps.forEach((s, i) => {
    const p = scope.part(s.id);
    if (p) traits(p, { grab: true, onPress: () => select(i) });
  });

  refresh();

  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 3);
      explodeNow += (explodeTarget - explodeNow) * k;
      scope.explode(explodeNow);
    },
  };
}
